/// <reference types="@stdlib/types"/>

import empty = require( '@stdlib/ndarray/base/empty' );
import zeros = require( '@stdlib/ndarray/base/zeros' );
import every = require( './index' );

/**
* Predicate function.
*
* @param x - input value
* @returns result
*/
function predicate( x: any ): boolean {
	return Boolean( x );
}

// The function returns an boolean...
{
	const sh = [ 2, 2 ];
	const ord = 'row-major';

	every( zeros( 'float64', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'float64', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'float32', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'float32', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'complex64', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'complex64', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'complex128', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'complex128', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'int32', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'int32', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'int16', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'int16', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'int8', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'int8', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'uint32', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'uint32', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'uint16', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'uint16', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'uint8', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'uint8', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'uint8c', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'uint8c', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( empty( 'bool', sh, ord ), predicate ); // $ExpectType boolean
	every( empty( 'bool', sh, ord ), predicate, {} ); // $ExpectType boolean
	every( zeros( 'generic', sh, ord ), predicate ); // $ExpectType boolean
	every( zeros( 'generic', sh, ord ), predicate, {} ); // $ExpectType boolean
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	every( 5, predicate ); // $ExpectError
	every( true, predicate ); // $ExpectError
	every( false, predicate ); // $ExpectError
	every( null, predicate ); // $ExpectError
	every( undefined, predicate ); // $ExpectError
	every( {}, predicate ); // $ExpectError
	every( [ 1 ], predicate ); // $ExpectError
	every( ( x: number ): number => x, predicate ); // $ExpectError
}

// The compiler throws an error if the function is provided a callback which is not a function...
{
	const x = zeros( 'generic', [ 2, 2 ], 'row-major' );

	every( x, '5' ); // $ExpectError
	every( x, true ); // $ExpectError
	every( x, false ); // $ExpectError
	every( x, null ); // $ExpectError
	every( x, undefined ); // $ExpectError
	every( x, {} ); // $ExpectError
	every( x, [ 1 ] ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	every(); // $ExpectError
	every( zeros( 'float64', [ 2, 2 ], 'row-major' ) ); // $ExpectError
	every( zeros( 'float64', [ 2, 2 ], 'row-major' ), {}, ( x: number ): number => x, {}, {} ); // $ExpectError
}
